class Solution {
public:
    string removeDuplicateLetters(string s) {
        map<char, int> last;
        for (int i = 0; i < (int)s.size(); i++) last[s[i]] = i;
        string st;
        set<char> inStack;
        for (int i = 0; i < (int)s.size(); i++) {
            char c = s[i];
            if (inStack.count(c)) continue;
            while (!st.empty() && st.back() > c && last[st.back()] > i) {
                inStack.erase(st.back());
                st.pop_back();
            }
            st.push_back(c);
            inStack.insert(c);
        }
        return st;
    }
};
